head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gBzProcsNo;
scwin.gListStatCd;
scwin.gDepCd; //20080908 담당팀 변수
scwin.vScrenID = "ULDSTF21600.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//20080908 담당팀과 담당자 가져오는 함수
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;

    //담당팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    dts_dep_1.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep_1.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp_1.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp_1.Reset();
};
scwin.fn_list_sync = function() {
    var vMarketTpCd = "";
    if (js_market == "1" || js_market == "2" || js_market == "6") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = $c.stf.getObjectValue(rdo_MARKET_TP_CD);
    }
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_ISUR_ETC_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.listedsearch.isuretcmodify.select.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_SDate) + // 시작일자
        "&{P}param02=" + $c.stf.getObjectValue(edt_EDate) + // 종료일자
        "&{P}param03=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드
        "&{P}param04=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드
        "&{P}param05=" + vMarketTpCd + // 시장구분
        "&{P}param06=" + vMarketTpCd + // 시장구분
        "&{P}param07=" + $c.stf.getObjectValue(cmb_TeamList_1) + // 담당팀
        "&{P}param08=" + $c.stf.getObjectValue(cmb_TeamList_1) + // 담당팀
        "&{P}param09=" + $c.stf.getObjectValue(cmb_EmpList_1) + // 담당자
        "&{P}param10=" + $c.stf.getObjectValue(cmb_EmpList_1) + // 담당자
        "&{P}param11=" + $c.stf.getObjectValue(rdo_LIST_PROCS_STAT_CD) + "&{P}param12=" + $c.stf.getObjectValue(rdo_LIST_PROCS_STAT_CD);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_setId = function(obj) {
    scwin.gBzProcsNo = dts_List.getCellData(eval(obj), "BZ_PROCS_NO");
    scwin.gListStatCd = dts_List.getCellData(eval(obj), "LIST_PROCS_STAT_CD");
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    $c.data.downloadGridViewExcel(grd_List, "법인 기타정보", "", "8");
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.grd_List_OnDblClick = async function(row, colid) {
    scwin.fn_setId(row);
    await $c.frame.CreateDialogFrame("gform", "/lstsrch/ULDSTF21601.gfm", "법인정보 수정", 200, 200, 675, 340, "window");
    scwin.fn_list_sync();
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.cmb_TeamList_1_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList_1, "VALUE", cmb_TeamList_1.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EmpList_1, '');
    }
    dts_emp_1.UseFilter = true;
    dts_emp_1.Filter();
    dts_emp_1.sort("DEP_CD", 0);
    //dts_emp_1.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_1_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp_1.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp_1.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.dts_emp_1_OnLoadError = function() {
    $c.stf.alert_error(dts_emp_1);
};
scwin.dts_dep_1_OnLoadError = function() {
    $c.stf.alert_error(dts_dep_1);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일주일전 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    if (js_market == "1" || js_market == "2" || js_market == "6") {
        $c.cm.setColumnProp(grd_List, "TR_MKT_NM", "Show", false);
        $c.stf.showObj(panel_mkt_gubun, false);
    } else {
        $c.stf.showObj(panel_mkt_gubun, true);
    }
    scwin.fn_SetCode(); //20080908 담당팀과 담당자 가져오는 부분
    scwin.fn_list_sync();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
